  _ = `%1$s (наследено)`,
  _ = `Връщане към набор от действия`,
  _ = `Разрешаване на редактиране`,
  _ = `%1$s (слой)`,
  _ = `Смяна на ляво с дясно`,
  _ = `Поведение`,
  _ = `%1$s — поведение`,
